import copy,csv,hashlib,html,importlib.util,json,math,sqlite3
from collections import defaultdict,Counter
from pathlib import Path
s=importlib.util.spec_from_file_location('m',Path(__file__).with_name('readability-model.py'))
m=importlib.util.module_from_spec(s);s.loader.exec_module(m)
out=m.ROOT/'output/final-review';out.mkdir(exist_ok=True)
read=lambda p:json.loads(p.read_text(encoding='utf8'))
sc=read(m.OUT/'native-validation.json');pcb=read(m.OUT/'pcb-native-review.json');physical=read(m.OUT/'physical-pcb-audit.json');sim=read(m.ROOT/'simulation/final-review/summary.json')
pcdoc=next(iter(m.io.documents(pcb['source']).values()));pa=m.io.attrs(pcdoc)
footprints={a['Designator']:a['Footprint'] for a in pa.values() if a.get('Designator') and a.get('Footprint')}
parts={};instances=0
for pg in sc['pages']:
    d=next(iter(m.io.documents(pg['source']).values()));aa=m.io.attrs(d)
    for (t,i),(_,p) in d['records'].items():
        a=aa.get(i,{})
        if t!='COMPONENT' or not a.get('Designator'):continue
        instances+=1;ref=a['Designator']
        if ref in parts:continue
        fp=footprints[ref];f=m.LIB[fp]
        value=a.get('Value') or a.get('Name')
        if value=='={Value}':value=a.get('Value')
        if value=='={Manufacturer Part}':value=a.get('Manufacturer Part')
        parts[ref]={'ref':ref,'page':'DAC8562' if pg['page']=='e58bcc16379b10f4' else 'DAC_MCU','value':value,'manufacturer':a.get('Manufacturer'),'manufacturerPart':a.get('Manufacturer Part'),'supplier':a.get('Supplier'),'supplierPart':a.get('Supplier Part') or None,'tolerance':a.get('Tolerance'),'tcr':a.get('Temperature Coefficient'),'footprintUuid':fp,'footprintName':f['head'].get('title') or f['head'].get('name'),'deviceUuid':a.get('Device'),'uniqueId':a.get('Unique ID'),'notes':'Manual precision procurement; do not substitute the underlying generic library resistor' if a.get('Supplier')=='Manual procurement' else ('Generic original connector; exact mating part and height need procurement confirmation' if ref=='J1' else '')}
assert len(parts)==154 and instances==158
groups=defaultdict(list)
for ref,p in parts.items():groups[(p['manufacturerPart'],p['footprintUuid'],p['supplierPart'],p['value'])].append(ref)
bom=[{**parts[refs[0]],'refs':sorted(refs),'quantity':len(refs)} for refs in groups.values()]
report={'date':'2026-10-13','physicalParts':154,'symbolInstances':158,'bomGroups':len(bom),'schematicErcPassed':all(p['passed'] and not p['details'] for p in sc['pages']),'pcbNativeDrcPassed':pcb['passed'],'pcbNativeDrcDetails':pcb['details'],'physicalCopperAuditPassed':physical['passed'],'analogSimulationPassed':sim['passed'],'analogSimulationCases':sim['caseCount'],'changes':['Schematic ordinary wiring restored within 06 functional blocks and DAC_MCU channels; labels/ports at inter-block boundaries and repeated supplies.','R117.2 schematic isolated net repaired to MCU_SENSE_B; original PCB was already correctly wired.','Q3 AO3400A replaced by onsemi 2N7002LT1G C16338, +/-20V gate rating. Actual stock SOT-23 footprint and pad-number mapping applied.','Four nearby VNEG12 segments rerouted; one GND trace/via added for R38; top ground clearance locally recomputed. No global rerouting or part relocation.'],'panelDecision':{'choice':'Single 100x100mm PCB; no mouse-bite copies created','assumption':'Small prototype batch, no assembly-volume requirement specified; manufacturer reference JLCPCB, not a placed order','reason':'Existing single board fits <=102x102mm special-price category. Routed/mouse-bite panel incurs normal engineering plus board cost and increases area. A two-up 2mm-gap, 5mm-rail example is at least 110x212mm before extra SMA-body clearance; 4-up is 212x212mm. SMA bodies protrude, rails/depaneling need assembly review. Low-volume single boards are preferable here.','exactPrice':'No binding quote; quantity, finish, shipping, tax and assembly service not specified','sources':['https://jlcpcb.com/help/article/in-what-cases-will-there-be-charged-extra','https://jlcpcb.com/capabilities/pcb-','https://jlcpcb.com/help/article/panelizing-your-pcb-for-assembly']},'releaseStatus':'Native ERC and physical checks complete; native PCB ECO synchronization pending' if not pcb['passed'] else 'CAD checks complete; conditional prototype release only, hardware qualification and fabrication DFM pending','noOrderPlaced':True,'limitations':sim['limitations']+['No hardware has been built or measured. No unconditional production/safety/accuracy certification.','J1 is a retained generic 2x5 female header; mating geometry and exact stock part need procurement confirmation.','Susumu precision resistors and explicitly manual YAGEO parts must be separately sourced; assembly/BOM inventory and final quotes are not guaranteed.','PGOOD is a rail window, not an accuracy flag. Lower rail limits do not guarantee full +/-10V op-amp headroom. AVDD upper threshold worst-case can reach 5.545V; normal LDO tolerance envelope is below 5.5V, but this window is not an overvoltage clamp.','TPS65131 peak switch-current limit vs L1/L2 saturation, MLCC effective capacitance, input inrush, startup/shutdown ripple and LDO thermal headroom need prototype qualification.','STM32 DAC cable capacitance above its <=50pF buffer specification needs a source-side buffer; receiver buffer does not remove cable capacitance. Outputs are high impedance-load drivers, not 50-ohm termination drivers.','A relay is not instantaneous. Test muted startup, power failure, contact bounce and input-cable disconnection before attaching external precision equipment.']}
release=read(out/'release-verification.json')
assert release['schematicErcPassed'] and release['pcbDrcPassed'] and pcb['passed'] and not pcb['details']
report['changes'].append('Final Q3 Name synchronization: fixed override removed, inherited ={Manufacturer Part}; native DRC clean. Automatic splitting of one collinear track leaves physical copper unchanged.')
report['releaseEvidence']=release
report['limitations'].append(release['schematicImageExportLimitation'])
(out/'review-summary.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf8')
(out/'BOM-reviewed.json').write_text(json.dumps({'parts':list(parts.values()),'grouped':bom,'physicalPartCount':154,'symbolInstanceCount':158},ensure_ascii=False,indent=2),encoding='utf8')
def esc(v):return html.escape(str(v or ''))
rows=''.join('<tr>'+''.join(f'<td>{esc(v)}</td>' for v in [', '.join(p['refs']),p['quantity'],p['value'],p['manufacturer'],p['manufacturerPart'],p['supplierPart'] or '수동 조달',p['tolerance'],p['footprintName'],p['notes']])+'</tr>' for p in bom)
css='body{font:16px/1.65 "Malgun Gothic",sans-serif;max-width:1180px;margin:40px auto;padding:0 24px;color:#23364a}h1,h2{line-height:1.3}h2{margin-top:36px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border:1px solid #d5dde4;padding:7px;text-align:left;vertical-align:top}th{background:#eaf0f4}a{color:#176aa1}.notice{padding:18px;background:#fff2db;border-left:5px solid #ce8000}.pass{color:#206744}code{background:#eef1f4;padding:2px 5px}li{margin:8px 0}'
(out/'BOM-reviewed.html').write_text(f'<!doctype html><html lang="ko"><meta charset="utf-8"><title>검토 BOM</title><style>{css}</style><h1>검토 BOM — 154개 실제 부품</h1><p>다중 유닛 심볼 158개를 실제 부품 154개로 합산했습니다. 아래 {len(bom)}개 그룹은 현재 두 페이지 및 실제 PCB 풋프린트에 근거합니다. 재고·가격·실장 서비스 승인까지 확정한 구매 BOM은 아닙니다. Q3는 onsemi 2N7002LT1G / C16338입니다.</p><table><thead><tr>'+''.join(f'<th>{x}</th>' for x in ['위치','수량','값','제조사','정확한 MPN','LCSC / 조달','허용오차','PCB 풋프린트','주의'])+'</tr></thead><tbody>'+rows+'</tbody></table></html>',encoding='utf8')
status='ERC 0건 / PCB 동박·간격 오류 0건 / 회로도–PCB 동기화 1건 남음' if not pcb['passed'] else 'ERC 0건 / PCB DRC 0건'
limits=''.join(f'<li>{esc(x)}</li>' for x in report['limitations'])
summary=f'''<!doctype html><html lang="ko"><meta charset="utf-8"><title>DAC8562 최종 재검토</title><style>{css}</style>
<h1>DAC8562 / DAC_MCU 최종 재검토</h1><p>2026-10-13 · 원본 프로젝트의 Page 1 / Page 2 및 Board1 · 100×100mm, 2층</p>
<div class="notice"><b>{status}</b><br>조건부 시제품 검토입니다. 제작사 DFM 및 실제 기동·정확도 검증 전 양산 승인 또는 외부 장비 연결 승인이 아닙니다. 주문하지 않았습니다.</div>
<h2>1. 회로도</h2><p>06 구역은 SPI 게이트 / 전원 감시 / 음전원 레벨 변환 / 기본 출력 뮤트로 나누고 블록 내부를 일반 와이어로 연결했습니다. DAC_MCU는 입력→버퍼→차동 출력의 피드백 배선을 직접 그렸으며 릴레이 블록 경계와 공통 전원·기준에만 포트·라벨을 사용했습니다. 두 페이지 모두 저장→닫기→재열기 후 ERC 통과입니다.</p>
<p><b>수정 1:</b> R117 뒤쪽의 회로도 누락을 MCU_SENSE_B에 연결했습니다. PCB는 원래 정상 연결이었습니다. <b>수정 2:</b> Q3의 VGS가 약 12.13V로 AO3400A의 ±12V 한계를 넘을 수 있어 ±20V 정격의 2N7002LT1G로 교체했습니다. 제조사 <a href="https://www.aosmd.com/sites/default/files/res/data_sheets/AO3400A.pdf">AO3400A</a>, <a href="https://www.onsemi.com/download/data-sheet/pdf/2n7002l-d.pdf">2N7002L</a> 정격·1=G/2=S/3=D 핀 배열 기준입니다.</p>
<p>AVDD = 1.185×(1+34k/10k) = 5.214V 명목. TPS7A49 전체 오차 ±2.5%와 저항 ±0.1%를 보수적으로 합산하면 약 5.076~5.352V입니다. LP2985는 단종이 아니지만 원래 5V 입력에서 5V 출력을 보장할 수 없어서 12V 후단 LDO로 바꾼 설계를 유지합니다. <a href="https://www.ti.com/lit/gpn/TPS7A49">TI TPS7A49</a></p>
<p>DAC8562 출력은 명목 4.115226×(VDAC−2.5V), 이론 ±10.288V 및 약 0.314mV/LSB입니다. 16비트가 곧 ±0.314mV 정확도를 의미하지 않습니다. INL 최대 ±12LSB는 출력 환산 약 ±3.77mV이고 기준·오프셋·이득·저항 오차는 별도입니다. 코드 범위 제한과 2점 보정이 필요합니다. <a href="https://www.ti.com/lit/gpn/dac8562t">TI DAC8562T</a></p>
<p>STM32H747 경로는 명목 (100k/14k)×(VIN−VREF+/2), VREF+=3.3V에서 0.25~3.05V→약 ±10V입니다. 출력 LSB는 약 5.75mV이므로 DAC8562와 같은 정밀도가 아닙니다. 내부 DAC 버퍼의 보증 출력 범위·부하 조건에 맞춰 제어하십시오. <a href="https://www.st.com/resource/en/datasheet/DM00602212.pdf">ST STM32H747 데이터시트</a></p>
<h2>2. BOM</h2><p><a href="BOM-reviewed.html">검토 BOM 보기</a> · <a href="BOM-reviewed.json">부품·그룹 데이터</a> · 154개 부품, 158개 심볼 인스턴스. Q1의 Si2323DDS 교체 유지, Q3는 C16338로 변경. TPS65131, DAC8562T, TPS7A49, TPS3700, OPA2277은 제조사 현행 제품 확인. L1/L2는 <a href="https://product.tdk.com/en/search/inductor/inductor/smd/info?part_no=B82462G4472M000">TDK Production</a> 상태입니다. 모든 수동 조달 부품의 납기·실장 가능성까지 확정한 것은 아닙니다.</p>
<h2>3. 시뮬레이션</h2><p>현재 24.3k/100k 및 14k/100k, 100Ω+22pF 이중 피드백, 출력 100pF, 접점 0.1Ω 기준으로 TI OPAx277 모델을 재실행했습니다. 10k/100k/1MΩ 부하와 추가 케이블 0/470/5000pF에서 AC·루프·스텝 54건, 느린 전범위 전환 4건 총 <b>58건 통과</b>. 최소 위상 여유 DAC8562 {sim['families']['DAC8562']['minimumPhaseMarginDeg']:.2f}°, MCU {sim['families']['MCU']['minimumPhaseMarginDeg']:.2f}°; 1% 스텝 정착 최악 {sim['families']['DAC8562']['maxSettling1PercentUs']:.2f} / {sim['families']['MCU']['maxSettling1PercentUs']:.2f}µs. 이는 DAC IC 자체의 정착·INL 보증과 다른 아날로그 증폭기 선별 결과입니다.</p>
<p>직접 DC/기본 OP 계산은 수렴 실패가 있어 실패 기록을 보관하고, ngspice의 문서화된 optran 초기화와 충분히 느린 전범위 transient plateau로 재검증했습니다. 실패한 DC sweep을 통과로 집계하지 않았습니다. 저항 ±0.05%만으로도 무보정 최악 오차 약 10.29mV / 10.44mV가 나옵니다. 정밀도는 실측 보정이 필요합니다. <a href="../../simulation/final-review/summary.json">전체 수치·제한</a></p>
<h2>4. PCB 배선</h2><p>두 구역의 100×100mm 배치를 유지했습니다. 실제 풋프린트와 PAD_NET을 대조하고 동박·패드·비아·GND 영역의 교차 연결을 독립 검사했습니다. 부품 패드 489개(연결 481개, NC 8개), 90개 네트에서 단선·단락 0건. Q3 주변만 새 풋프린트에 맞춰 VNEG12 우회 및 R38 GND 비아를 추가했습니다. Native DRC의 물리적 간격·연결 오류는 0건입니다.</p>
<p>마지막 비교 창의 Q3:Name 한 건을 기본 <code>={{Manufacturer Part}}</code> 표시로 동기화하여, 저장 후 재열기에서 EasyEDA PCB DRC도 0건으로 통과했습니다. 마지막 ECO는 표시 속성만 변경했고 기존 직선 트랙의 자동 분할은 동박 모양·폭·네트를 바꾸지 않았습니다. <a href="q3-name-change-audit.json">변경 대조</a> · <a href="release-verification.json">저장·제작 파일 검증</a></p>
<p><b>최신 수정본:</b> <a href="DAC8562 module_final_review_ERC_DRC_clean.eprj2">EasyEDA 편집 프로젝트</a> · <a href="DAC8562 module_final_review_ERC_DRC_clean.epro2">이식용 프로젝트 export</a> · <a href="DAC8562_DAC_MCU_100x100_final_Gerber.zip">Native Gerber</a> · <a href="DAC8562_DAC_MCU_100x100_final_Gerber_DFM.zip">실크 간격 보정 Gerber</a>. 이전 pcb-two-zone Gerber는 Q3의 이전 풋프린트이므로 이번 수정본 제작에 사용하지 마십시오.</p>
<p>DFM 사본은 상면 실크만 마스크에서 약 0.15mm, 외곽에서 0.15mm 이격하도록 잘랐습니다. 동박·마스크·외곽·드릴 파일은 Native export와 바이트 단위 동일합니다. 100×100mm 외곽, 비아 134개, 고정홀 4개를 실제 Gerber에서 대조했습니다. Combined PTH에는 비아가 포함되므로 Via-only DRL은 중복 참고용이며 추가 드릴 패스로 사용하지 마십시오.</p>
<img src="gerber-dfm-top-preview.png" alt="최신 Gerber에서 렌더링한 상면 — DAC8562 위, DAC_MCU 아래" style="width:100%;max-width:900px"><p>위 그림은 실제 최신 Gerber 렌더링입니다. 회로도 PNG/SVG export는 현재 EasyEDA 3.2.149에서 timeout이 발생하여 캐시 썸네일을 최신 가독성 검증 이미지로 사용하지 않았습니다. 현재 회로도 소스, 재열기 ERC 및 export의 부품·핀 네트·일반 와이어 형태는 별도 대조했습니다. <a href="schematic-export-audit.json">회로도 export 대조</a></p>
<h2>패널 결정: 단일 보드 유지</h2><p>시제품 소량 기준으로 복제 마우스바이트 패널을 만들지 않습니다. 현재 보드는 단일 ≤102×102mm 특가 구간에 들어가지만 routed/mouse-bite 패널은 일반 engineering fee+board fee 대상입니다. 2개를 2mm 간격·5mm 레일로 묶는 단순 예만 해도 최소 110×212mm이고 4개는 212×212mm가 됩니다. 실제 SMA 몸체 간섭 여유는 추가로 필요합니다. 면적·가공비·분리 스트레스가 늘고, 현재 물량에서 조립 효율 이점은 확인되지 않았습니다. 수량·표면처리·배송·세금이 미정이므로 확정 견적 금액은 제시하지 않습니다. <a href="https://jlcpcb.com/help/article/in-what-cases-will-there-be-charged-extra">JLCPCB 요금 규정</a>, <a href="https://jlcpcb.com/capabilities/pcb-">패널 가공 규격</a>, <a href="https://jlcpcb.com/help/article/panelizing-your-pcb-for-assembly">조립 패널 권고</a></p>
<p>추후 50개 이상 실장 요구가 확정되면 제조사의 실장 공정에 맞춰 2-up 패널과 단일 수량의 동일 납품 수량 견적을 비교하십시오. 마우스바이트는 2mm 간격, 최소 5mm 탭, 제조사 검토된 홀 규칙·레일·돌출 커넥터 금지영역 기준으로 새로 설계해야 합니다. 현재 Panel1은 변경하지 않았습니다.</p>
<h2>제작 후 필수 검증</h2><ul>{limits}</ul><p>권장 순서: 5V 입력과 ±12V/AVDD 상승·하강·오버슈트 → GPIO/SPI 차단 → muted DAC 초기화 → 더미 고임피던스 부하에서 ±9.5V부터 케이블 안정성 → 보정 및 허용 코드 확정 → 외부 장비 연결.</p>
<p>요청된 Git 전달 여부는 실제 커밋 및 origin/main HEAD로 확인합니다. 이 보고서는 CAD 검사 증거이며 미래 push를 예측하지 않습니다. 제작·실장 주문은 하지 않았습니다.</p></html>'''
(out/'final-review.html').write_text(summary,encoding='utf8')
print(json.dumps({'report':str(out/'final-review.html'),'BOMGroups':len(bom),'physicalParts':154,'nativeErc':report['schematicErcPassed'],'nativePcbDrc':report['pcbNativeDrcPassed'],'physicalCopper':physical['passed'],'simulation':sim['passed'],'panel':'single'},ensure_ascii=False))
